on.value:
@if(
    and(
        and(
            equals(item().SourceSystem,'OnPremSQL'),
            equals(item().LoadType,'FULL')
        ),
        or(
            and(
                equals(item().SourceSchema,'Person'),
                equals(item().SourceTable,'Address')
            ),
            and(
                equals(item().SourceSchema,'HumanResources'),
                equals(item().SourceTable,'Employee')
            )
        )
    ),
    if(
        and(
            equals(item().SourceSchema,'Person'),
            equals(item().SourceTable,'Address')
        ),
        'OnPremSQL_FULL_ADDRESS',
        'OnPremSQL_FULL_EMPLOYEE'
    ),
    concat(item().SourceSystem,'_',item().LoadType)
)

